const req=$('TEMP Bilingual Entry').first().json.body;
if(req?.authorization!=='bilingual-20261005'||!['ready','first_fails','kit_failure'].includes(req.scenario))throw new Error('Controlled bilingual request required');
const saved=$('TEMP Bilingual Manifest').first().json.nodes.find(n=>n.name==='TEMP Deep Fixture').parameters.jsCode;
const lookup=name=>{
 if(name==='TEMP Deep Entry')return {first:()=>({json:{body:{authorization:'deep-cn-interface-20261005',scenario:'ready'}}})};
 if(name==='TEMP Deep Read Handoff')return $('TEMP Bilingual Handoff');
 if(name==='TEMP Deep Read Writing')return $('TEMP Bilingual Writing');
 throw new Error('Unexpected fixture dependency');
};
return new Function('$',saved)(lookup);

const scenario=$('TEMP Bilingual Entry').first().json.body.scenario;
return $input.all().map((row,i)=>{const w=row.json,d=w.writer_invocation_decision;
 if(!d||w.task_config.language!==d.target_language)throw new Error('Prepared language binding missing');
 return {json:{...w,writer_invocation_decision:{...d,authorization_kind:'controlled_test',
  target_language:scenario==='first_fails'&&i===0?'en-US':d.target_language,
  decision_source:{type:'user_chat_authorization',reference:'AI_Daily:bilingual:mother_execution:'+$execution.id},
  side_effects_isolated:true}},pairedItem:{item:i}};
});

const b=$input.first().json,s=$('TEMP Bilingual Entry').first().json.body.scenario;
const check=(x,m)=>{if(!x)throw new Error('Bilingual acceptance: '+m);};
check(b.expected_languages.join(',')==='zh-CN,en-US'&&Object.keys(b.versions).length===2,'two languages');
check(b.publication.state==='NOT_PUBLISHED'&&!b.rejected_results.length,'delivery boundary');
if(s==='first_fails')check(b.delivery_status==='partial'&&b.versions['zh-CN'].status==='FAILED'&&b.versions['en-US'].status==='DRAFT','first failure lost sibling');
else if(s==='kit_failure')check(b.delivery_status==='partial'&&b.versions['zh-CN'].preview.social_kit_status==='failed'&&b.versions['zh-CN'].article.markdown.includes('合成测试正文')&&b.versions['en-US'].status==='DRAFT','Kit failure lost article or sibling');
else {
 check(b.delivery_status==='completed','both complete');
 const work=$('Prepare Writer Invocation').all().map(r=>r.json);
 check(JSON.stringify(work[0].writing_input)===JSON.stringify(work[1].writing_input),'material drift');
 for(const lang of b.expected_languages){const v=b.versions[lang],p=v.preview;
  check(v.language===lang&&v.social_kit.language===lang&&v.status==='DRAFT','localized package');
  check(p.writer_invocation_receipt.authorization_kind==='controlled_test','test provenance');
  check(p.image_counts.failed===0&&p.assembly_status==='completed','visual completion');
  let t=v.article.markdown;for(const img of v.body_images){check(t.includes(img.markdown_insertion),'body image missing');t=t.replace(img.markdown_insertion,'');}
  check(t===p.article_markdown&&p.draft_markdown.length>0,'prose changed or draft lost');
 }
}
const packages=Object.fromEntries(Object.entries(b.versions).map(([lang,{preview,...v}])=>[lang,v]));
const counts=Object.fromEntries(Object.entries(b.versions).map(([lang,v])=>[lang,{draft_chars:v.preview?.draft_markdown?.length,article_chars:v.article?.markdown?.length,image_counts:v.preview?.image_counts,body_images:v.body_images?.length}]));
return [{json:{test:'bilingual_default',scenario:s,passed:true,formal_hitl:false,delivery_status:b.delivery_status,counts,packages},pairedItem:{item:0}}];

const x=$input.first().json,lang=x.writer_brief.language,zh=lang==='zh-CN';
const title=zh?'双语合成测试':'Bilingual synthetic test';
const article='# '+title+'\n\n'+(zh?'合成测试正文，非真实文章。':'Synthetic test text, not a real article.');
return [{json:{schema:'writing_preview.v1',content_id:x.content_id,story_id:x.story_id,story_mode:x.story_mode,language:lang,config:x.writer_context.config,writer_invocation_receipt:x.writer_invocation_receipt,article_title:title,article_markdown:article,draft_markdown:article,status:'draft',editing_status:'completed',image_assets:[],warnings:[],publication:{state:'NOT_PUBLISHED',url:null}},pairedItem:{item:0}}];

